primaryQuery:
run: order_items -> {
  where: delivered_at is not null
  group_by: order_year is year(created_at)
  aggregate: avg_days_to_deliver is round(avg(days(created_at::date to delivered_at)), 3)
  order_by: order_year
  calculate: prior_year_days is lag(avg_days_to_deliver)
} -> {
  where: order_year = 2022
  select:
    avg_days_2022 is avg_days_to_deliver
    avg_days_2021 is prior_year_days
    yoy_change_days is round(avg_days_to_deliver - prior_year_days, 3)
}

verifyQuery:
run: order_items -> {
  where: delivered_at is not null
  aggregate:
    avg_days_2022 is round(avg(days(created_at::date to delivered_at)) { where: year(created_at) = 2022 }, 3)
    avg_days_2021 is round(avg(days(created_at::date to delivered_at)) { where: year(created_at) = 2021 }, 3)
} -> {
  select:
    avg_days_2022
    avg_days_2021
    yoy_change_days is round(avg_days_2022 - avg_days_2021, 3)
}
